624:      }
625:      if (!supportsCustomTools && call.type === "custom_tool_call") {
626:        call.type = "function_call";
627:        call.arguments = JSON.stringify({ content: typeof call.input === "string" ? call.input : "" });
628:        delete call.input;
629:      } else if (call.type === "function_call") {
630:        call.arguments = normalizeFunctionArguments(call.arguments);
631:      }
632:      out.push(call);
633:      continue;
634:    }
635:    if (item.type === "function_call_output" || item.type === "custom_tool_call_output") {
636:      const callId = item.call_id || item.id;
637:      if (!callId || seenOutputs.has(callId)) continue;
638:      seenOutputs.add(callId);
639:      let output = item.output;
640:      if (Array.isArray(output)) {
641:        const filtered = dropToolOutputImages(output, model);
642:        output = filtered;
643:        // Responses expects output as string, like Chat's tool message content.
644:        // Stringify array to preserve text, matching buildMessages behavior.
645:        if (Array.isArray(output)) {
646:          if (output.length === 0) output = "";
647:          else if (output.every((p) => p && typeof p.text === "string")) output = output.map((p) => p.text).join("\n");
648:          else output = JSON.stringify(output);
649:        }
650:      }
651:      if (output && typeof output === "object" && !Array.isArray(output)) output = JSON.stringify(output);
652:      if (typeof output !== "string") output = String(output ?? "");
653:      out.push({
654:        type: !supportsCustomTools && item.type === "custom_tool_call_output" ? "function_call_output" : item.type,
655:        call_id: callId,
656:        output,
657:      });
658:      continue;
659:    }
660:    if (item.type === "message") {
661:      const role = item.role === "developer" || item.role === "system" || item.role === "assistant" ? item.role : "user";
