667:          const t = role === "assistant" ? "output_text" : "input_text";
668:          out.push({ type: "message", role, content: [{ type: t, text: rawText }] });
669:        }
670:        continue;
671:      }
672:      out.push({ type: "message", role, content: parts });
673:      continue;
674:    }
675:    if (item.type === "agent_message") {
676:      const text = agentMessageText(item);
677:      if (text) out.push({ type: "message", role: "user", content: [{ type: "input_text", text }] });
678:      continue;
679:    }
680:    if (item.type === "compaction" || item.type === "context_compaction") {
681:      const summary = decodeSummary(item.encrypted_content);
682:      const text = summary ? SUMMARY_PREFIX + "\n\n" + summary : "Earlier conversation history was compacted in an unreadable format.";
