bun -e '
async function testFetchDecompress() {
  const payload = JSON.stringify({hello:"world"});
  const compressed = Bun.zstdCompressSync(Buffer.from(payload));
  console.log("compressed len", compressed.length, "orig", payload.length);
  const server = Bun.serve({
    port: 0,
    fetch(req) {
      const enc = req.headers.get("accept-encoding") || "";
      console.log("server saw accept-encoding:", enc);
      return new Response(compressed, {headers: {"Content-Type":"application/json", "Content-Encoding":"zstd"}});
    }
  });
  const url = "http://127.0.0.1:"+server.port+"/";
  // default fetch
  let res = await fetch(url);
  console.log("default fetch content-encoding:", res.headers.get("content-encoding"));
  console.log("default fetch text head:", (await res.arrayBuffer()).byteLength, "bytes");
  // try res.json
  let res2 = await fetch(url);
  try { const j = await res2.json(); console.log("res.json ok:", JSON.stringify(j)); } catch(e){ console.log("res.json fail:", e.message); }
  // try with manual decompress
  let res3 = await fetch(url);
  const buf = Buffer.from(await res3.arrayBuffer());
  console.log("raw first bytes:", buf.slice(0,10));
  try { const dec = Bun.zstdDecompressSync(buf); console.log("manual zstd dec:", Buffer.from(dec).toString()); } catch(e){ console.log("manual dec fail", e.message); }
  server.stop(true);
}
await testFetchDecompress();
' 2>&1

