async function testIncoming() {
  const server = Bun.serve({
    port: 0,
    async fetch(req) {
      const ce = req.headers.get("content-encoding") || "";
      console.log("server saw content-encoding:", JSON.stringify(ce));
      console.log("content-type:", req.headers.get("content-type"));
      const raw = Buffer.from(await req.arrayBuffer());
      console.log("raw len:", raw.length, "first20:", raw.slice(0,20));
      try { const j = await (async()=>{ const r2 = raw; return JSON.parse(Buffer.from(r2).toString()); })(); console.log("manual parse ok?", JSON.stringify(j).slice(0,100)); } catch(e){ console.log("manual parse fail:", e.message.slice(0,200)); }
      // try req.json() on a fresh read? cant re-read. So test with second server
      return new Response("ok");
    }
  });
  const url = "http://127.0.0.1:"+server.port+"/";
  const payload = JSON.stringify({model:"test", input:[1,2,3]});
  const compressed = Bun.zstdCompressSync(Buffer.from(payload));
