bun -e '
async function testStreamZstd() {
  const encoder = new TextEncoder();
  // Simulate upstream SSE chunks compressed with zstd as a whole? Or per-chunk?
  // Most servers compress the entire stream with content-encoding, not per-chunk.
  const sseText = "data: {\"choices\":[{\"delta\":{\"content\":\"hello\"}}]}\n\ndata: [DONE]\n\n";
  const compressed = Bun.zstdCompressSync(Buffer.from(sseText));
  console.log("sse len", sseText.length, "compressed", compressed.length);
  const server = Bun.serve({
    port: 0,
    fetch(req) {
      console.log("accept-encoding:", req.headers.get("accept-encoding"));
      return new Response(compressed, {headers: {"Content-Type":"text/event-stream", "Content-Encoding":"zstd"}});
    }
  });
  const url = "http://127.0.0.1:"+server.port+"/";
  const res = await fetch(url);
  console.log("res content-encoding:", res.headers.get("content-encoding"));
  console.log("res content-type:", res.headers.get("content-type"));
  const text = await res.text();
  console.log("decompressed text:", JSON.stringify(text).slice(0,200));
  console.log("match?", text===sseText);
  server.stop(true);
}
await testStreamZstd();
' 2>&1

