    const comp = Buffer.from(Bun.zstdCompressSync(jsonBytes));
    return new Response(comp, {headers:{"Content-Type":"application/json", "Content-Encoding":"zstd"}});
  }
});
const dir = mkdtempSync(path.join(tmpdir(), "repro3-"));
const configPath = path.join(dir, "codextras.json");
