1:import { randomUUID } from "node:crypto";
2:
3:export function uuid() {
4:  return randomUUID().replaceAll("-", "");
5:}
6:
7:export function newId(prefix) {
8:  return prefix + "_" + uuid();
9:}
10:
11:export function messageItem(text) {
12:  return { type: "message", role: "user", content: [{ type: "input_text", text }] };
13:}
14:
15:export function sse(type, data, sequence) {
16:  const payload = { type: type, ...data };
17:  if (sequence !== undefined) payload.sequence_number = sequence;
18:  return "event: " + type + "\ndata: " + JSON.stringify(payload) + "\n\n";
19:}
20:
21:export function sseDone() {
22:  return "data: [DONE]\n\n";
23:}
24:
25:export const COMPACTION_PREFIX = "kcr1:";
26:
27:export const SUMMARY_PREFIX =
28:  "Another language model started this task and produced a continuation summary. Use it to continue without repeating completed work:";
29:
30:export const COMPACT_PROMPT =
31:  "You are performing a CONTEXT CHECKPOINT COMPACTION. Create a handoff summary for another language model that will resume the task.\n\n" +
32:  "Include current progress, key decisions, constraints, user preferences, remaining steps, and critical data or references. Be concise, structured, and focused on seamless continuation.";
33:
34:export function encodeSummary(summary) {
35:  return COMPACTION_PREFIX + Buffer.from(summary, "utf8").toString("base64");
36:}
37:
38:export function decodeSummary(value) {
39:  if (typeof value !== "string" || !value.startsWith(COMPACTION_PREFIX)) return undefined;
40:  try {
41:    return Buffer.from(value.slice(COMPACTION_PREFIX.length), "base64").toString("utf8");
42:  } catch {
43:    return undefined;
44:  }
45:}
46:
47:export function textOf(item) {
48:  if (!item || !Array.isArray(item.content)) return "";
49:  return item.content
50:    .map((part) => (part && typeof part.text === "string" ? part.text : ""))
51:    .join("");
52:}
53:
54:export function reasoningItemText(item) {
55:  const summary = item && item.summary;
56:  if (typeof summary === "string" && summary) return summary;
57:  if (Array.isArray(summary)) {
58:    const text = summary
59:      .map((part) => (part && typeof part.text === "string" ? part.text : undefined))
60:      .filter(Boolean)
61:      .join("\n");
62:    if (text) return text;
63:  }
64:  const content = item && item.content;
65:  if (typeof content === "string" && content) return content;
66:  if (Array.isArray(content)) {
67:    const text = content
68:      .map((part) => (part && typeof part.text === "string" ? part.text : undefined))
69:      .filter(Boolean)
70:      .join("\n");
71:    if (text) return text;
72:  }
73:  return undefined;
74:}
75:
76:// Native OpenAI encrypted tokens are dense base64-ish blobs with no spaces.
77:// Routed handoffs are stored as readable plaintext; only those are inlinable.
78:export function isOpaqueToken(value) {
79:  return typeof value === "string" && value.length > 40 && !/\s/.test(value);
80:}
81:
82:export function estimateTokensFromBytes(bytes) {
83:  return Math.max(1, Math.ceil(bytes / 4));
84:}
85:
86:export function estimateTokensFromText(text) {
87:  const bytes = Buffer.byteLength(text || "", "utf8");
88:  return Math.max(0, Math.ceil(bytes / 4));
89:}
