// Request/response body decompression. The desktop client may send
// zstd-encoded JSON bodies (Content-Encoding: zstd) which Bun.serve does not
// decode automatically, and some upstreams return zstd bytes without a
// Content-Encoding header. Bun.fetch already transparently decodes bodies
// that carry a Content-Encoding header, so upstream handling only needs a
// fallback for the headerless case; request handling must honor the header.
function normalizeEncoding(name) {
  const v = String(name || "").trim().toLowerCase();
  if (!v || v === "identity") return "identity";
  if (v === "zstd" || v === "x-zstd" || v === "zstandard") return "zstd";
  if (v === "gzip" || v === "x-gzip") return "gzip";
  if (v === "deflate") return "deflate";
  if (v === "br" || v === "brotli") return "br";
  return v;
}

export function parseContentEncodings(headerValue) {
  if (!headerValue) return [];
  return String(headerValue)
    .split(",")
    .map(normalizeEncoding)
    .filter((v) => v && v !== "identity");
}

function bunDecompress(encoding, bytes) {
  try {
    const bun = globalThis.Bun;
    if (!bun) return undefined;
    if (encoding === "zstd" && typeof bun.zstdDecompressSync === "function") {
      return Buffer.from(bun.zstdDecompressSync(bytes));
    }
    if (encoding === "gzip" && typeof bun.gunzipSync === "function") {
      return Buffer.from(bun.gunzipSync(bytes));
    }
    if (encoding === "deflate" && typeof bun.inflateSync === "function") {
      return Buffer.from(bun.inflateSync(bytes));
    }
  } catch {}
  return undefined;
