function decompressOne(bytes, encoding) {
  const enc = normalizeEncoding(encoding);
  if (enc === "identity") return Buffer.from(bytes);
  if (enc === "zstd") {
    const viaBun = bunDecompress("zstd", bytes);
    if (viaBun !== undefined) return viaBun;
    try {
      if (typeof zlib.zstdDecompressSync === "function") return Buffer.from(zlib.zstdDecompressSync(bytes));
    } catch {}
    return undefined;
