// Read an upstream error body as text, decoding zstd/gzip/etc. when the raw
// bytes are compressed (headerless or otherwise).
export async function readUpstreamText(res) {
  let bytes;
  try {
    bytes = Buffer.from(await res.arrayBuffer());
  } catch {
    return "";
  }
  if (!bytes.length) return "";
  let header = "";
  try {
    header = res.headers ? res.headers.get("content-encoding") || "" : "";
  } catch {}
  const byHeader = decompressByHeader(bytes, header);
  if (byHeader !== undefined) {
    const parsed = tryParseJsonBytes(byHeader);
    if (parsed.ok) {
      try {
        return byHeader.toString("utf8");
      } catch {}
    } else {
      try {
        const text = byHeader.toString("utf8");
        if (text && !text.includes("\uFFFD") || looksLikeZstd(bytes) || looksLikeGzip(bytes)) return text;
      } catch {}
    }
  }
  const ordered = [];
  if (looksLikeZstd(bytes)) ordered.push("zstd");
  if (looksLikeGzip(bytes)) ordered.push("gzip");
  for (const enc of ["zstd", "gzip", "br", "deflate"]) {
    if (ordered.includes(enc)) continue;
    ordered.push(enc);
  }
  for (const enc of ordered) {
    if (parseContentEncodings(header).includes(enc) && byHeader !== undefined) continue;
    const next = decompressOne(bytes, enc);
    if (next === undefined) continue;
    try {
      const text = next.toString("utf8");
      const parsed = tryParseJsonBytes(next);
      if (parsed.ok) return text;
      if (looksLikeZstd(bytes) || looksLikeGzip(bytes)) return text;
    } catch {}
  }
  try {
    return bytes.toString("utf8");
  } catch {
    return "";
  }
}

