6:function outputText(json) {
7:  const message = json.choices && json.choices[0] && json.choices[0].message;
8:  let text = "";
9:  if (message && typeof message.content === "string") text += message.content;
10:  if (message && typeof message.reasoning_content === "string") text += message.reasoning_content;
11:  for (const tc of Array.isArray(message && message.tool_calls) ? message.tool_calls : []) {
12:    if (tc && tc.function && typeof tc.function.arguments === "string") {
13:      text += tc.function.arguments;
14:    }
15:  }
16:  return text;
17:}
