19:export function convertChatJsonToResponses({ json, requestedModel, requestBytes, toolNames, customNames }) {
20:  const names = toolNames instanceof Map ? toolNames : new Map();
21:  const custom = customNames instanceof Set ? customNames : new Set();
22:  const usage = finalizeUsage(
23:    usageFromPayload(json),
24:    fallbackFrom(requestBytes, outputText(json)),
25:  );
26:  const output = [];
27:  const message = json.choices && json.choices[0] && json.choices[0].message;
28:  if (message && typeof message.reasoning_content === "string" && message.reasoning_content) {
29:    output.push({
30:      type: "reasoning",
31:      id: newId("rs"),
32:      summary: [{ type: "summary_text", text: message.reasoning_content }],
33:    });
34:  }
35:  if (message && typeof message.content === "string" && message.content) {
36:    output.push({
37:      type: "message",
38:      id: newId("msg"),
39:      status: "completed",
40:      role: "assistant",
41:      content: [{ type: "output_text", text: message.content, annotations: [] }],
42:    });
43:  }
44:  for (const tc of Array.isArray(message && message.tool_calls) ? message.tool_calls : []) {
45:    if (!tc || !tc.id) continue;
46:    const fn = tc.function || {};
47:    const item = toolCallItem({
48:      callId: tc.id,
49:      name: typeof fn.name === "string" ? fn.name : "",
50:      args: typeof fn.arguments === "string" ? fn.arguments : "",
51:      status: "completed",
52:      customNames: custom,
53:    });
54:    const mapped = names.get(item.name) || mapToolName(item.name);
55:    if (mapped) {
56:      item.name = mapped.name;
57:      item.namespace = mapped.namespace;
58:    }
59:    output.push(item);
60:  }
61:  return {
62:    id: newId("resp"),
63:    object: "response",
64:    created_at: Math.floor(Date.now() / 1000),
65:    status: "completed",
66:    model: requestedModel,
67:    output,
68:    usage,
69:    error: null,
70:  };
71:}
