bun -e '
import { tmpdir } from "node:os";
import path from "node:path";
import { mkdtempSync, writeFileSync } from "node:fs";
import { createMockProvider } from "./smoke/mock-provider.mjs";
const mock = createMockProvider();
const dir = mkdtempSync(path.join(tmpdir(), "repro-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({gateway:{port:0, pathPrefix:"/_codextras"}, providers:[{id:"mock", type:"openai-chat", baseUrl:"http://127.0.0.1:"+mock.port, apiKeyEnv:"K"}], models:[{alias:"test-model", provider:"mock", upstreamModel:"mock-upstream"}]}));
process.env.CODEXTRAS_CONFIG=configPath;
process.env.K="sk-test";
const {createServer} = await import("./src/server.mjs");
const {loadConfig} = await import("./src/config.mjs");
const server = createServer(loadConfig(), "s3cr3t");
const base="http://127.0.0.1:"+server.port+"/_codextras/s3cr3t";
async function post(body, headers) {
  const res = await fetch(base+"/v1/responses", {method:"POST", headers, body});
  const text = await res.text();
  return {status: res.status, text};
}
const payload = JSON.stringify({model:"test-model", input:[{type:"message", role:"user", content:[{type:"input_text", text:"hi"}]}], stream:false});
console.log("1 plain:", (await post(payload, {"Content-Type":"application/json"})).status);
const zstd = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));
let r = await post(zstd, {"Content-Type":"application/json", "Content-Encoding":"zstd"});
console.log("2 zstd header:", r.status, r.text.slice(0,200));
// zstd without header (sniff)
r = await post(zstd, {"Content-Type":"application/json"});
console.log("3 zstd no-header sniff:", r.status, r.text.slice(0,200));
// gzip
const gz = Buffer.from(Bun.gzipSync(Buffer.from(payload)));
r = await post(gz, {"Content-Type":"application/json", "Content-Encoding":"gzip"});
console.log("4 gzip:", r.status, r.text.slice(0,200));
// br via node:zlib
import { brotliCompressSync } from "node:zlib";
const br = Buffer.from(brotliCompressSync(Buffer.from(payload)));
r = await post(br, {"Content-Type":"application/json", "Content-Encoding":"br"});
console.log("5 br:", r.status, r.text.slice(0,200));
// deflate
const df = Buffer.from(Bun.deflateSync(Buffer.from(payload)));
r = await post(df, {"Content-Type":"application/json", "Content-Encoding":"deflate"});
console.log("6 deflate:", r.status, r.text.slice(0,200));
// zstd streaming
const payloadStream = JSON.stringify({model:"test-model", input:[{type:"message", role:"user", content:[{type:"input_text", text:"hi"}]}], stream:true});
const zstdS = Buffer.from(Bun.zstdCompressSync(Buffer.from(payloadStream)));
r = await post(zstdS, {"Content-Type":"application/json", "Content-Encoding":"zstd"});
console.log("7 zstd stream:", r.status, r.text.slice(0,300).replace(/\n/g,"|"));
server.stop(true); mock.stop(true);
' 2>&1

