import path from "node:path";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
const upstream = Bun.serve({
  port: 0,
  async fetch(req) {
    const body = await req.json();
    const resp = {id:"chatcmpl-mock", object:"chat.completion", created: 123, model: body.model, choices:[{index:0, message:{role:"assistant", content:"hi zstd raw", reasoning_content:"r"}, finish_reason:"stop"}], usage:{prompt_tokens:1, completion_tokens:1, total_tokens:2}};
    const comp = Buffer.from(Bun.zstdCompressSync(Buffer.from(JSON.stringify(resp))));
    return new Response(comp, {headers:{"Content-Type":"application/json"}});
  }
});
const dir = mkdtempSync(path.join(tmpdir(), "repro2-"));
const configPath = path.join(dir, "codextras.json");
writeFileSync(configPath, JSON.stringify({gateway:{port:0, pathPrefix:"/_codextras"}, providers:[{id:"mock", type:"openai-chat", baseUrl:"http://127.0.0.1:"+upstream.port, apiKeyEnv:"K"}], models:[{alias:"test-model", provider:"mock", upstreamModel:"mock-upstream"}]}));
process.env.CODEXTRAS_CONFIG=configPath;
process.env.K="sk-test";
const {createServer} = await import("./src/server.mjs");
const {loadConfig} = await import("./src/config.mjs");
const server = createServer(loadConfig(), "s3cr3t");
const base="http://127.0.0.1:"+server.port+"/_codextras/s3cr3t";
const payload = JSON.stringify({model:"test-model", input:[{type:"message", role:"user", content:[{type:"input_text", text:"hi"}]}], stream:false});
let res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: payload});
console.log("upstream raw zstd status", res.status);
console.log((await res.text()).slice(0,800));
// test upstream returning non-object JSON (array)
upstream.stop(true);
const upstream2 = Bun.serve({port:0, async fetch(){ return new Response(JSON.stringify([1,2,3]), {headers:{"Content-Type":"application/json"}}); }});
