const base2="http://127.0.0.1:"+server2.port+"/_codextras/s3cr3t2";
res = await fetch(base2+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body: payload});
console.log("upstream array status", res.status);
console.log((await res.text()).slice(0,800));
server.stop(true); server2.stop(true); upstream2.stop(true);
