{"code":"const r = await tools.bash({command: 'bun -e \'\nimport { tmpdir } from "node:os";\nimport path from "node:path";\nimport { mkdtempSync, writeFileSync } from "node:fs";\nimport { createMockProvider } from "./smoke/mock-provider.mjs";\nconst mock = createMockProvider();\nconst dir = mkdtempSync(path.join(tmpdir(), "final-"));\nconst configPath = path.join(dir, "codextras.json");\nwriteFileSync(configPath, JSON.stringify({gateway:{port:0, pathPrefix:"/_codextras"}, providers:[{id:"mock", type:"openai-chat", baseUrl:"http://127.0.0.1:"+mock.port, apiKeyEnv:"K"}], models:[{alias:"test-model", provider:"mock", upstreamModel:"m"}]}));\nprocess.env.CODEXTRAS_CONFIG=configPath;\nprocess.env.K="sk-test";\nconst {createServer} = await import("./src/server.mjs");\nconst {loadConfig} = await import("./src/config.mjs");\nconst server = createServer(loadConfig(), "s3");\nconst base="http://127.0.0.1:"+server.port+"/_codextras/s3";\nconst payload = JSON.stringify({model:"test-model", input:[{type:"message", role:"user", content:[{type:"input_text", text:"hi"}]}], stream:false});\nfor (const [name, enc, compFn] of [["zstd","zstd",(b)=>Buffer.from(Bun.zstdCompressSync(b))],["gzip","gzip",(b)=>Buffer.from(Bun.gzipSync(b))]]) {\n  const c = compFn(Buffer.from(payload));\n  let res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json","Content-Encoding":enc}, body:c});\n  console.log(name, res.status, res.status===200?"PASS":"FAIL");\n}\n// headerless zstd\n{\n  const c = Buffer.from(Bun.zstdCompressSync(Buffer.from(payload)));\n  let res = await fetch(base+"/v1/responses", {method:"POST", headers:{"Content-Type":"application/json"}, body:c});\n  console.log("zstd-headerless", res.status, res.status===200?"PASS":"FAIL");\n}\nserver.stop(true); mock.stop(true);\n\' 2>&1', description: 'Final zstd verification'});
console.log(r.stdout.text);
return "ok";
","description":"Final verification"}

